\n/*\n# SafeOps AI — Phase 1 Baseline Schema\n\n## Summary\nCreates all core tables for SafeOps AI, an HSE operational support platform for Nigerian oil & gas operations (NEPL). This migration establishes the full data model for Phase 1 including user profiles, chat, knowledge base, risk assessments, toolbox talks, emergency cards, observations, and governance.\n\n## New Tables\n1. **profiles** — extends Supabase auth.users with employee_id, role, department, location, asset_type. Each user has one profile.\n2. **chat_sessions** — AI chat conversation threads per user with session type and status.\n3. **chat_messages** — individual messages in a chat session (user or assistant), including governance metadata.\n4. **knowledge_categories** — hierarchical categories for HSE documents (e.g. Process Safety, Drilling, PTW).\n5. **knowledge_documents** — HSE procedures, SOPs, guidelines with version control and approval status.\n6. **emergency_cards** — quick-access emergency response cards for scenarios like gas release, fire, MOB.\n7. **risk_assessments** — JSA/TRA/hazard ID records generated or approved by supervisors and managers.\n8. **risk_assessment_steps** — step-level breakdown of each risk assessment with hazards, controls, ratings.\n9. **toolbox_talks** — AI-generated toolbox talk content for pre-job safety briefings.\n10. **observations** — safety observations (unsafe acts, near misses, positives) submitted by field staff.\n11. **governance_reviews** — queue for reviewing flagged AI responses and document accuracy.\n\n## Security\n- RLS enabled on all tables.\n- Authenticated users can read/write their own records.\n- Cross-reads allowed for shared reference data (knowledge, emergency cards).\n- Service role bypasses RLS for seeding and admin operations.\n\n## Notes\n- Uses auth.uid() for ownership;
 profiles.id references auth.users(id).\n- All tables use UUID primary keys.\n- Seed data inserted for knowledge_categories and emergency_cards.\n*/\n\n-- ============================================================\n-- PROFILES\n-- ============================================================\nCREATE TABLE IF NOT EXISTS profiles (\n  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  employee_id varchar(20) UNIQUE NOT NULL,\n  full_name varchar(100) NOT NULL,\n  role varchar(30) NOT NULL DEFAULT 'field_worker'\n    CHECK (role IN ('admin', 'hse_manager', 'hse_advisor', 'supervisor', 'field_worker', 'contractor', 'auditor')),\n  department varchar(50) DEFAULT 'Operations',\n  location varchar(50) DEFAULT 'Lagos',\n  asset_type varchar(30) DEFAULT 'platform',\n  phone varchar(20),\n  avatar_url varchar(255),\n  is_active boolean DEFAULT true,\n  preferences jsonb DEFAULT '{}',\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "profiles_select" ON profiles;
\nCREATE POLICY "profiles_select" ON profiles FOR SELECT TO authenticated USING (true);
\n\nDROP POLICY IF EXISTS "profiles_insert_own" ON profiles;
\nCREATE POLICY "profiles_insert_own" ON profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);
\n\nDROP POLICY IF EXISTS "profiles_update_own" ON profiles;
\nCREATE POLICY "profiles_update_own" ON profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
\n\n-- ============================================================\n-- CHAT SESSIONS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS chat_sessions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,\n  title varchar(200) DEFAULT 'New Conversation',\n  session_type varchar(30) DEFAULT 'general'\n    CHECK (session_type IN ('general', 'risk_assessment', 'ptw_guidance', 'incident_investigation', 'toolbox_talk', 'emergency')),\n  status varchar(20) DEFAULT 'active'\n    CHECK (status IN ('active', 'archived', 'flagged')),\n  operational_context jsonb DEFAULT '{}',\n  message_count int DEFAULT 0,\n  last_message_at timestamptz,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE chat_sessions ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "chat_sessions_select_own" ON chat_sessions;
\nCREATE POLICY "chat_sessions_select_own" ON chat_sessions FOR SELECT TO authenticated USING (auth.uid() = user_id);
\n\nDROP POLICY IF EXISTS "chat_sessions_insert_own" ON chat_sessions;
\nCREATE POLICY "chat_sessions_insert_own" ON chat_sessions FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
\n\nDROP POLICY IF EXISTS "chat_sessions_update_own" ON chat_sessions;
\nCREATE POLICY "chat_sessions_update_own" ON chat_sessions FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
\n\nDROP POLICY IF EXISTS "chat_sessions_delete_own" ON chat_sessions;
\nCREATE POLICY "chat_sessions_delete_own" ON chat_sessions FOR DELETE TO authenticated USING (auth.uid() = user_id);
\n\n-- ============================================================\n-- CHAT MESSAGES\n-- ============================================================\nCREATE TABLE IF NOT EXISTS chat_messages (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  session_id uuid NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES auth.users(id),\n  role varchar(20) NOT NULL CHECK (role IN ('user', 'assistant', 'system')),\n  content text NOT NULL,\n  content_type varchar(20) DEFAULT 'text' CHECK (content_type IN ('text', 'voice_transcript', 'structured', 'error')),\n  model_used varchar(50),\n  confidence_score decimal(3,2),\n  safety_flag boolean DEFAULT false,\n  escalation_triggered boolean DEFAULT false,\n  escalation_reason varchar(100),\n  governance_status varchar(20) DEFAULT 'pending' CHECK (governance_status IN ('pending', 'approved', 'rejected', 'escalated')),\n  citations jsonb DEFAULT '[]',\n  metadata jsonb DEFAULT '{}',\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE chat_messages ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "chat_messages_select_own" ON chat_messages;
\nCREATE POLICY "chat_messages_select_own" ON chat_messages FOR SELECT TO authenticated\n  USING (EXISTS (SELECT 1 FROM chat_sessions WHERE id = chat_messages.session_id AND user_id = auth.uid()));
\n\nDROP POLICY IF EXISTS "chat_messages_insert_own" ON chat_messages;
\nCREATE POLICY "chat_messages_insert_own" ON chat_messages FOR INSERT TO authenticated\n  WITH CHECK (EXISTS (SELECT 1 FROM chat_sessions WHERE id = chat_messages.session_id AND user_id = auth.uid()));
\n\n-- ============================================================\n-- KNOWLEDGE CATEGORIES\n-- ============================================================\nCREATE TABLE IF NOT EXISTS knowledge_categories (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name varchar(100) NOT NULL UNIQUE,\n  code varchar(20) NOT NULL UNIQUE,\n  description text,\n  risk_level varchar(20) CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),\n  icon varchar(30),\n  applicable_assets text[] DEFAULT '{}',\n  display_order int DEFAULT 0,\n  is_active boolean DEFAULT true,\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE knowledge_categories ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "knowledge_categories_select" ON knowledge_categories;
\nCREATE POLICY "knowledge_categories_select" ON knowledge_categories FOR SELECT TO authenticated USING (true);
\n\n-- ============================================================\n-- KNOWLEDGE DOCUMENTS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS knowledge_documents (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  title varchar(255) NOT NULL,\n  document_code varchar(50) NOT NULL UNIQUE,\n  category_id uuid NOT NULL REFERENCES knowledge_categories(id),\n  document_type varchar(30) CHECK (document_type IN ('procedure', 'sop', 'manual', 'guideline', 'alert', 'lesson_learned', 'regulatory', 'emergency_plan')),\n  description text,\n  content text,\n  version varchar(10) DEFAULT '1.0',\n  status varchar(20) DEFAULT 'approved' CHECK (status IN ('draft', 'under_review', 'approved', 'archived', 'superseded')),\n  risk_level varchar(20) CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),\n  asset_types text[] DEFAULT '{}',\n  departments text[] DEFAULT '{}',\n  is_contractor_visible boolean DEFAULT false,\n  is_emergency_critical boolean DEFAULT false,\n  review_date date,\n  metadata_tags text[] DEFAULT '{}',\n  created_by uuid REFERENCES auth.users(id),\n  approved_at timestamptz DEFAULT now(),\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE knowledge_documents ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "knowledge_documents_select" ON knowledge_documents;
\nCREATE POLICY "knowledge_documents_select" ON knowledge_documents FOR SELECT TO authenticated USING (true);
\n\nDROP POLICY IF EXISTS "knowledge_documents_insert" ON knowledge_documents;
\nCREATE POLICY "knowledge_documents_insert" ON knowledge_documents FOR INSERT TO authenticated WITH CHECK (true);
\n\nDROP POLICY IF EXISTS "knowledge_documents_update" ON knowledge_documents;
\nCREATE POLICY "knowledge_documents_update" ON knowledge_documents FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
\n\n-- ============================================================\n-- EMERGENCY CARDS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS emergency_cards (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  title varchar(100) NOT NULL,\n  scenario varchar(50) NOT NULL\n    CHECK (scenario IN ('gas_release', 'fire', 'medical', 'man_overboard', 'blowout', 'spill', 'evacuation', 'collision', 'structural', 'h2s')),\n  severity varchar(20) DEFAULT 'critical' CHECK (severity IN ('high', 'critical')),\n  quick_actions text[] DEFAULT '{}',\n  checklist_items text[] DEFAULT '{}',\n  escalation_contacts jsonb DEFAULT '[]',\n  muster_points jsonb DEFAULT '[]',\n  equipment_needed text[] DEFAULT '{}',\n  color varchar(20) DEFAULT 'red',\n  icon varchar(30),\n  is_active boolean DEFAULT true,\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE emergency_cards ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "emergency_cards_select" ON emergency_cards;
\nCREATE POLICY "emergency_cards_select" ON emergency_cards FOR SELECT TO authenticated USING (true);
\n\n-- ============================================================\n-- RISK ASSESSMENTS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS risk_assessments (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),\n  assessment_type varchar(20) CHECK (assessment_type IN ('JSA', 'TRA', 'hazard_id')),\n  title varchar(255) NOT NULL,\n  activity_description text,\n  location varchar(100),\n  department varchar(50),\n  asset_type varchar(30),\n  overall_risk_rating varchar(20),\n  residual_risk_rating varchar(20),\n  status varchar(20) DEFAULT 'draft' CHECK (status IN ('draft', 'completed', 'approved', 'archived')),\n  approved_by uuid REFERENCES auth.users(id),\n  approved_at timestamptz,\n  ai_generated boolean DEFAULT true,\n  created_at timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE risk_assessments ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "risk_assessments_select" ON risk_assessments;
\nCREATE POLICY "risk_assessments_select" ON risk_assessments FOR SELECT TO authenticated USING (true);
\n\nDROP POLICY IF EXISTS "risk_assessments_insert" ON risk_assessments;
\nCREATE POLICY "risk_assessments_insert" ON risk_assessments FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
\n\nDROP POLICY IF EXISTS "risk_assessments_update" ON risk_assessments;
\nCREATE POLICY "risk_assessments_update" ON risk_assessments FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
\n\n-- ============================================================\n-- RISK ASSESSMENT STEPS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS risk_assessment_steps (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  assessment_id uuid NOT NULL REFERENCES risk_assessments(id) ON DELETE CASCADE,\n  step_number int NOT NULL,\n  activity_step text NOT NULL,\n  hazards text[] DEFAULT '{}',\n  risk_before_likelihood int CHECK (risk_before_likelihood BETWEEN 1 AND 5),\n  risk_before_severity int CHECK (risk_before_severity BETWEEN 1 AND 5),\n  risk_before_rating varchar(20),\n  control_measures text[] DEFAULT '{}',\n  risk_after_likelihood int CHECK (risk_after_likelihood BETWEEN 1 AND 5),\n  risk_after_severity int CHECK (risk_after_severity BETWEEN 1 AND 5),\n  risk_after_rating varchar(20),\n  responsible_person varchar(100),\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE risk_assessment_steps ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "ra_steps_select" ON risk_assessment_steps;
\nCREATE POLICY "ra_steps_select" ON risk_assessment_steps FOR SELECT TO authenticated USING (true);
\n\nDROP POLICY IF EXISTS "ra_steps_insert" ON risk_assessment_steps;
\nCREATE POLICY "ra_steps_insert" ON risk_assessment_steps FOR INSERT TO authenticated WITH CHECK (\n  EXISTS (SELECT 1 FROM risk_assessments WHERE id = risk_assessment_steps.assessment_id AND user_id = auth.uid())\n);
\n\n-- ============================================================\n-- TOOLBOX TALKS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS toolbox_talks (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),\n  title varchar(255) NOT NULL,\n  activity varchar(100),\n  location varchar(100),\n  crew_size int DEFAULT 5,\n  duration_minutes int DEFAULT 15,\n  discussion_points text[] DEFAULT '{}',\n  hazards text[] DEFAULT '{}',\n  controls text[] DEFAULT '{}',\n  questions text[] DEFAULT '{}',\n  environmental_conditions varchar(100),\n  status varchar(20) DEFAULT 'draft',\n  conducted_at timestamptz,\n  ai_generated boolean DEFAULT true,\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE toolbox_talks ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "toolbox_talks_select" ON toolbox_talks;
\nCREATE POLICY "toolbox_talks_select" ON toolbox_talks FOR SELECT TO authenticated USING (true);
\n\nDROP POLICY IF EXISTS "toolbox_talks_insert" ON toolbox_talks;
\nCREATE POLICY "toolbox_talks_insert" ON toolbox_talks FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
\n\nDROP POLICY IF EXISTS "toolbox_talks_update" ON toolbox_talks;
\nCREATE POLICY "toolbox_talks_update" ON toolbox_talks FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
\n\n-- ============================================================\n-- OBSERVATIONS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS observations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),\n  observation_type varchar(30) CHECK (observation_type IN ('unsafe_act', 'unsafe_condition', 'near_miss', 'positive_observation', 'environmental')),\n  category varchar(50),\n  description text NOT NULL,\n  location varchar(100),\n  severity varchar(20) CHECK (severity IN ('low', 'medium', 'high', 'critical')),\n  ai_recommendation text,\n  status varchar(20) DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'closed', 'escalated')),\n  assigned_to uuid REFERENCES auth.users(id),\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE observations ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "observations_select" ON observations;
\nCREATE POLICY "observations_select" ON observations FOR SELECT TO authenticated USING (true);
\n\nDROP POLICY IF EXISTS "observations_insert" ON observations;
\nCREATE POLICY "observations_insert" ON observations FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
\n\nDROP POLICY IF EXISTS "observations_update" ON observations;
\nCREATE POLICY "observations_update" ON observations FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
\n\n-- ============================================================\n-- GOVERNANCE REVIEWS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS governance_reviews (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  message_id uuid REFERENCES chat_messages(id),\n  review_type varchar(30) DEFAULT 'ai_response' CHECK (review_type IN ('ai_response', 'document_content', 'citation_accuracy')),\n  status varchar(20) DEFAULT 'pending' CHECK (status IN ('pending', 'under_review', 'approved', 'rejected', 'escalated')),\n  flagged_by uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),\n  flagged_reason text,\n  reviewed_by uuid REFERENCES auth.users(id),\n  review_notes text,\n  reviewed_at timestamptz,\n  priority varchar(10) DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'critical')),\n  created_at timestamptz DEFAULT now()\n);
\n\nALTER TABLE governance_reviews ENABLE ROW LEVEL SECURITY;
\n\nDROP POLICY IF EXISTS "governance_reviews_select" ON governance_reviews;
\nCREATE POLICY "governance_reviews_select" ON governance_reviews FOR SELECT TO authenticated USING (true);
\n\nDROP POLICY IF EXISTS "governance_reviews_insert" ON governance_reviews;
\nCREATE POLICY "governance_reviews_insert" ON governance_reviews FOR INSERT TO authenticated WITH CHECK (auth.uid() = flagged_by);
\n\nDROP POLICY IF EXISTS "governance_reviews_update" ON governance_reviews;
\nCREATE POLICY "governance_reviews_update" ON governance_reviews FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
\n\n-- ============================================================\n-- SEED: KNOWLEDGE CATEGORIES\n-- ============================================================\nINSERT INTO knowledge_categories (name, code, description, risk_level, icon, applicable_assets, display_order) VALUES\n('HSE Management System', 'HSE-MS', 'Overall HSE management framework, policies, and standards', 'medium', 'Shield', '{"rig","platform","terminal","construction"}', 1),\n('Process Safety', 'PSM', 'Process hazard analysis, barrier management, and process safety management', 'critical', 'AlertTriangle', '{"platform","terminal"}', 2),\n('Drilling Safety', 'DRILL-SAFE', 'Well control, drilling operations, and blowout prevention', 'critical', 'Drill', '{"rig"}', 3),\n('Lifting Operations', 'LIFT-OPS', 'Crane operations, rigging, and lifting equipment management', 'high', 'ArrowUp', '{"rig","platform","construction"}', 4),\n('Confined Space Entry', 'CSE', 'Confined space assessment, entry procedures, and rescue', 'critical', 'Lock', '{"rig","platform","terminal","construction"}', 5),\n('Working at Height', 'WAH', 'Work at height, scaffolding, and fall protection', 'high', 'Mountain', '{"rig","platform","construction"}', 6),\n('Electrical Safety', 'ELEC-SAFE', 'Electrical isolation, LOTO, and live electrical work', 'high', 'Zap', '{"rig","platform","terminal","construction"}', 7),\n('Permit to Work', 'PTW', 'Hot work, cold work, confined space, and critical lifting permits', 'critical', 'FileCheck', '{"rig","platform","terminal","construction"}', 8),\n('Emergency Response', 'EMERGENCY', 'Emergency response plans, procedures, and drills', 'critical', 'AlertOctagon', '{"rig","platform","terminal","construction"}', 9),\n('Environmental Management', 'ENV-MGMT', 'Spill response, waste management, and environmental compliance', 'high', 'Leaf', '{"rig","platform","terminal","construction"}', 10),\n('Contractor Safety', 'CONT-SAFE', 'Contractor HSE requirements, pre-qualification, and site rules', 'medium', 'Users', '{"rig","platform","terminal","construction"}', 11),\n('Marine Operations', 'MARINE', 'Marine safety, vessel operations, and man overboard procedures', 'high', 'Anchor', '{"rig","platform"}', 12),\n('SIMOPS', 'SIMOPS', 'Simultaneous operations risk management and coordination', 'critical', 'GitBranch', '{"rig","platform"}', 13),\n('Incident Investigation', 'INC-INV', 'Root cause analysis, 5 Why, and corrective actions', 'high', 'Search', '{"rig","platform","terminal","construction"}', 14),\n('Occupational Health', 'OCC-HEALTH', 'Health surveillance, ergonomics, and occupational hygiene', 'medium', 'Heart', '{"rig","platform","terminal","construction"}', 15)\nON CONFLICT (code) DO NOTHING;
\n\n-- ============================================================\n-- SEED: KNOWLEDGE DOCUMENTS\n-- ============================================================\nINSERT INTO knowledge_documents (title, document_code, category_id, document_type, description, version, status, risk_level, is_contractor_visible, is_emergency_critical, metadata_tags) VALUES\n('Confined Space Entry Procedure', 'NEPL-CSE-001', (SELECT id FROM knowledge_categories WHERE code = 'CSE'), 'procedure', 'Standard procedure for confined space identification, risk assessment, entry, and rescue. Covers atmosphere testing, isolation, standby arrangements, and emergency procedures.', '3.2', 'approved', 'critical', true, true, '{"confined-space","entry","atmosphere-testing","rescue"}'),\n('Hot Work Permit Procedure', 'NEPL-PTW-001', (SELECT id FROM knowledge_categories WHERE code = 'PTW'), 'procedure', 'Permit requirements for all hot work activities including welding, cutting, grinding. Covers fire watch, gas testing, and safe area classification.', '2.1', 'approved', 'critical', true, false, '{"hot-work","welding","permit","fire-watch"}'),\n('Well Control Procedure', 'NEPL-DRILL-001', (SELECT id FROM knowledge_categories WHERE code = 'DRILL-SAFE'), 'procedure', 'Well kick detection, BOP operations, kill procedures, and blowout prevention for drilling and completion operations.', '4.0', 'approved', 'critical', false, true, '{"well-control","kick","BOP","blowout"}'),\n('Lifting Operations Standard', 'NEPL-LIFT-001', (SELECT id FROM knowledge_categories WHERE code = 'LIFT-OPS'), 'sop', 'Crane pre-use inspection, rigging requirements, lift categories (routine/complex/critical), and signaling procedures.', '2.3', 'approved', 'high', true, false, '{"crane","rigging","lifting","slinging"}'),\n('Gas Release Emergency Response', 'NEPL-EMRG-001', (SELECT id FROM knowledge_categories WHERE code = 'EMERGENCY'), 'emergency_plan', 'Immediate response to hydrocarbon gas releases including detection, isolation, ignition prevention, and evacuation procedures.', '1.5', 'approved', 'critical', true, true, '{"gas-release","hydrocarbon","evacuation","ESD"}'),\n('H2S Safety Procedure', 'NEPL-OCC-001', (SELECT id FROM knowledge_categories WHERE code = 'OCC-HEALTH'), 'procedure', 'H2S hazard awareness, SCBA use, detection equipment, muster procedures, and first aid for H2S exposure.', '2.0', 'approved', 'critical', true, true, '{"H2S","hydrogen-sulfide","SCBA","toxic-gas"}'),\n('Work at Height Procedure', 'NEPL-WAH-001', (SELECT id FROM knowledge_categories WHERE code = 'WAH'), 'procedure', 'Fall protection requirements, scaffold inspection, harness use, and ladder safety for all elevated work activities.', '3.1', 'approved', 'high', true, false, '{"WAH","scaffolding","harness","fall-protection"}'),\n('SIMOPS Management Procedure', 'NEPL-SIM-001', (SELECT id FROM knowledge_categories WHERE code = 'SIMOPS'), 'procedure', 'Risk assessment and coordination requirements for simultaneous operations on offshore facilities including drilling-production interface.', '1.8', 'approved', 'critical', false, false, '{"SIMOPS","simultaneous-operations","offshore","coordination"}'),\n('Incident Investigation Guideline', 'NEPL-INC-001', (SELECT id FROM knowledge_categories WHERE code = 'INC-INV'), 'guideline', 'Step-by-step guide for incident notification, scene preservation, root cause analysis, and corrective action tracking.', '2.4', 'approved', 'high', false, false, '{"incident","investigation","root-cause","5-why"}'),\n('Marine Man Overboard Procedure', 'NEPL-MAR-001', (SELECT id FROM knowledge_categories WHERE code = 'MARINE'), 'emergency_plan', 'Immediate actions for man overboard situations, rescue operations, and post-incident reporting for all marine and offshore personnel.', '1.3', 'approved', 'critical', true, true, '{"MOB","man-overboard","rescue","marine"}'),\n('Electrical Isolation LOTO Procedure', 'NEPL-ELEC-001', (SELECT id FROM knowledge_categories WHERE code = 'ELEC-SAFE'), 'procedure', 'Lockout/tagout procedures for electrical isolation, zero energy verification, and safe re-energization of electrical equipment.', '2.6', 'approved', 'high', true, false, '{"LOTO","isolation","electrical","lockout-tagout"}'),\n('Process Safety Management Standard', 'NEPL-PSM-001', (SELECT id FROM knowledge_categories WHERE code = 'PSM'), 'manual', 'NEPL PSM standard covering PHA, MOC, pre-startup safety review, and mechanical integrity for process facilities.', '1.0', 'approved', 'critical', false, false, '{"PSM","process-safety","PHA","barrier-management"}')\nON CONFLICT (document_code) DO NOTHING;
\n\n-- ============================================================\n-- SEED: EMERGENCY CARDS\n-- ============================================================\nINSERT INTO emergency_cards (title, scenario, severity, quick_actions, checklist_items, equipment_needed, color, icon, escalation_contacts) VALUES\n('Gas Release Response', 'gas_release', 'critical',\n  ARRAY['STOP all ignition sources immediately', 'Activate ESD / Emergency Shutdown', 'Sound general alarm', 'Muster at designated assembly point', 'Do NOT re-enter until all-clear given'],\n  ARRAY['Identify and isolate gas source if safe to do so', 'Check wind direction - stay upwind', 'Notify OIM / Installation Manager immediately', 'Activate ESD system', 'Account for all personnel at muster', 'Await emergency response team instruction', 'Initiate standby vessel alert', 'Contact NEPL Emergency Hotline'],\n  ARRAY['SCBA', 'Gas detector', 'Fire extinguisher', 'ESD panel key', 'Emergency radio'],\n  'red', 'AlertTriangle',\n  '[{"name":"OIM Emergency Line","phone":"+234-800-NEPL-OIM"},{"name":"NEPL Emergency Control","phone":"+234-800-NEPL-ECC"},{"name":"Standby Vessel","phone":"VHF CH16"}]'\n),\n('Fire Response', 'fire', 'critical',\n  ARRAY['Sound fire alarm immediately', 'Call emergency number', 'Evacuate area - close doors behind you', 'Muster at assembly point', 'DO NOT use lifts'],\n  ARRAY['Confirm fire location and type', 'Activate CO2/Halon if in equipment room', 'Isolate electrical supply if safe', 'Account for all personnel', 'Deploy fire team to scene', 'Prepare for potential evacuation', 'Keep access routes clear for fire team', 'Contact NEPL Emergency Control'],\n  ARRAY['Fire extinguisher', 'SCBA', 'Fire hose', 'Personal escape set', 'Emergency communication'],\n  'red', 'Flame',\n  '[{"name":"Fire Team Leader","phone":"Emergency Radio CH1"},{"name":"OIM","phone":"+234-800-NEPL-OIM"},{"name":"NEPL Emergency Control","phone":"+234-800-NEPL-ECC"}]'\n),\n('Man Overboard', 'man_overboard', 'critical',